def factorial(n: int) -> int:
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value

def unique(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return seen

def index_of(items, value):
    for i, item in enumerate(items):
        if item == value:
            return i
    return -1

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    x, y = a, b
    while y:
        x, y = y, x % y
    return a // x * b

def power(base, exp):
    result = 1
    for _ in range(exp):
        result *= base
    return result

def temperature_status(temp):
    if temp >= 30:
        return 'hot'
    if temp <= 10:
        return 'cold'
    return 'mild'

def grade(score):
    if score >= 90:
        return 'A'
    if score >= 70:
        return 'B'
    if score >= 50:
        return 'C'
    return 'F'
